{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"application_screening_fees","lifecycle":"enacted","title":"California maximum tenant screening fee (2026)","requirement":"A landlord may charge a prospective tenant no more than the annual maximum screening fee ($68.96 for 2026) and must give the applicant a copy of any consumer credit report obtained, a receipt, an itemized expense list, and a refund of any unused portion.","key_value":"$68.96 for 2026","coverage_conditions":"All landlords charging tenant screening fees to prospective tenants in California.","applicability":{"conditions":[],"per_tenancy":"Applies when a landlord charges a screening fee to a prospective tenant.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":"2026","valid_through":"2026","citation":"Cal. Civ. Code § 1950.6","quoted_span":"The maximum tenant screening fee for 2026 is\n$68.96","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"CA","category":"screening_restrictions","lifecycle":"enacted","title":"California reusable tenant screening report requirement","requirement":"If a prospective tenant provides a reusable screening report, the landlord must use it.","key_value":null,"coverage_conditions":"All landlords screening prospective tenants in California.","applicability":{"conditions":[],"per_tenancy":"Applies when a prospective tenant provides a reusable screening report.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Cal. Civ. Code § 1950.6","quoted_span":"If the tenant provides a reusable screening report, the landlord must use it.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
{"packet_id":"D005-01","doc_id":"D005","jurisdiction":"Berkeley, CA","category":"application_screening_fees","lifecycle":"enacted","title":"Berkeley tenant screening fee disclosure and non-refundable application fee ban","requirement":"An owner or agent who charges an applicant a screening fee must first give a tenant screening fee rights statement and the state maximum fee cap, and may not charge an existing tenant a non-refundable fee to renew a tenancy or to add or replace a roommate.","key_value":null,"coverage_conditions":"All residential rental agreements in Berkeley, regardless of any contrary lease language.","applicability":{"conditions":[],"per_tenancy":"Applies to owners or agents charging applicants a screening fee, and to fees charged to existing tenants for renewals or roommate changes.","coverage_quotes":[]},"exemptions":null,"penalty":null,"effective_date":null,"valid_through":null,"citation":"Berkeley Mun. Code ch. 13.78","quoted_span":"An owner of residential rental property (or the owner’s agent) cannot charge a non-refundable fee to any existing tenant for the purpose of renewing a tenancy, in whole or in part, including any fee associated with the departure of a roommate or to request to add or replace a roommate in a pre-existing household.","interaction":null,"relations":[],"confidence":0.8,"conflict_flag":false,"conflict_note":null}
